insert into public.quiz_questions
  (qid, unit, sub, difficulty, question, choice_a, choice_b, choice_c, choice_d, correct, explanation, source, active)
values
  ('SHIORI-001', '安全のしおり', '安全理念', '★', 'ベステラの安全理念「基本3ヶ条」として定められているものはどれか。', '安全は全てに優先する', '品質は全てに優先する', '納期は全てに優先する', 'コストは全てに優先する', 'A', '基本3ヶ条は「①安全は全てに優先する ②自ら考え、工夫し、努力する ③環境に配慮し、循環社会に貢献する」。安全が最優先される。', '安全のしおり 工事部員心得 安全理念 基本3ヶ条', true),
  ('SHIORI-002', '安全のしおり', '一般事項', '★★', '客先・工場内の現場での行為として、規則上「禁止」されているものはどれか。', '客先が許可した場所での休憩', '無許可での撮影・SNSへのアップロード', '支給された作業服の着用', '許可された場所での飲食', 'B', '客先・工場内現場での無許可の撮影・スケッチ・SNSアップロードは禁止。現場によっては通話も禁止される場合があり、客先ルールをよく確認する。', '安全のしおり 1-1 現場 ②', true),
  ('SHIORI-003', '安全のしおり', '飲酒・喫煙', '★', '現場での喫煙に関する規則として正しいものはどれか。', '携帯灰皿を使えばどこでも喫煙してよい', '構内駐車中の車内なら喫煙してよい', '許可された場所以外での喫煙は、携帯灰皿を使用しても不可', '移動中の車内なら喫煙してよい', 'C', '許可を受けた場所以外での飲食・喫煙は禁止。喫煙は携帯灰皿を使用しても不可で、構内駐車・移動中の車内なども不可。', '安全のしおり 1-2 飲食・飲酒・喫煙 ①', true),
  ('SHIORI-004', '安全のしおり', '服装(現場)', '★', '現場での服装規則として正しいものはどれか。', '夏場は半袖・腕まくりで作業してよい', 'ヘルメットはアゴ紐をしっかり掛けて着用する', '暑い日は手ぬぐいを首に掛けてよい', 'ヘルメットの下に頭巻きをしてよい', 'B', 'ヘルメットはアゴ紐をしっかり掛ける。現場内では半袖・腕まくり作業は禁止、手ぬぐい・タオルの首(腰)掛け禁止、ヘルメット下の頭巻きも禁止。', '安全のしおり 1-3 服装(現場) ①④⑤', true),
  ('SHIORI-005', '安全のしおり', '交通規則', '★★', '自動車の運転に関する規則として誤っているものはどれか。', '連続運転は2時間ごとに休憩を取る', '運転中の携帯電話の操作は禁止', '社有車はベステラ社員以外も運転してよい', '運転業務の開始前後にアルコールチェックを行う', 'C', '社有車はベステラ社員以外の運転を禁止。連続運転は2時間で休憩、運転中の携帯操作禁止、運転業務の開始前後にアルコールチェックを行う。', '安全のしおり 1-4 交通規則 ②③⑨⑩', true),
  ('SHIORI-006', '安全のしおり', '作業前', '★★', 'プラント等の現場で作業に着手する際、着工許可を得る相手として正しいものはどれか。', '自社の上長', '客先責任者', '協力会社責任者', '玉掛け作業者', 'B', 'プラント等の現場では、作業の着手に客先責任者の着工許可を得る。', '安全のしおり 2-1 作業前 ②', true),
  ('SHIORI-007', '安全のしおり', '作業中', '★★★', '当初の予定になかった作業（予定外作業）が発生したときの正しい対応はどれか。', 'そのまま継続し、後で報告する', '一度作業を止め、客先に確認し、承認後に再KYを行ってから作業する', '作業指揮者の判断だけで進める', '翌日の朝礼で共有してから着手する', 'B', '予定外作業が発生したら一度作業を止め、客先に確認し作業手順を確認、客先承認後に再KYを行ってから作業する。', '安全のしおり 2-2 作業中 ②', true),
  ('SHIORI-008', '安全のしおり', '緊急時対応', '★★', '事故等の連絡を行う際の正しい方法はどれか。', '口頭で簡単に伝える', '5W1Hで的確に行う', 'メールのみで連絡する', '連絡に集中し、現場把握は後回しにする', 'B', '事故等の連絡は5W1Hで的確に行う。ただし連絡に気をとられ過ぎず、現場の把握・安全確保を確実に実施する。', '安全のしおり 2-6 緊急時対応 ③④', true),
  ('SHIORI-009', '安全のしおり', '現場管理(元請)', '★★', '元請として行うべき事項として正しいものはどれか。', '作業場所の巡視は週1回でよい', '協議会組織を設置し毎月1回以上開催する', '連絡調整は協力会社に任せる', '巡視は災害発生時のみ行う', 'B', '元請は協議会組織を設置し毎月1回以上開催、作業間の連絡調整、1日1回以上の作業場所巡視等を行う。', '安全のしおり 3 現場管理(元請) ①③', true),
  ('SHIORI-010', '安全のしおり', '火気作業', '★★', '火気作業を行った後の残火確認について、正しいものはどれか。', '5分以上', '10分以上', '30分以上', '確認は不要', 'C', '火気作業を行った際は30分以上、残火確認を確実に行う。', '安全のしおり 4-2 火気作業 ⑦', true),
  ('SHIORI-011', '安全のしおり', '火気作業', '★★★', 'アセチレンボンベの取り扱いとして正しいものはどれか。', '横に寝かせて使用する', '立てて使用し、転倒防止のチェーン(2重)等で固縛する', '直射日光下で50度まで許容される', '固縛は不要', 'B', 'アセチレンボンベは必ず立てて使用し、転倒防止用チェーン(2重)等で固縛。直射日光を避け40度以下に保つため防炎シート等で被う。', '安全のしおり 4-2 火気作業 ⑤', true),
  ('SHIORI-012', '安全のしおり', '高所作業', '★★', '墜落制止用器具に関する規則として正しいものはどれか。', '2m以上で器具を使用し、5m以上でフルハーネス型を使用する', '3m以上で器具を使用すればよい', 'フルハーネス型は10m以上で義務付けられる', '使用期限切れの器具でも持込み可', 'A', '2m以上の高所で墜落制止用器具を使用し、5m以上でフルハーネス型が義務。持込時点検を実施し、使用期限切れ・規格外器具の持込は禁止。', '安全のしおり 4-3 高所作業 ②', true),
  ('SHIORI-013', '安全のしおり', '高所作業', '★★', 'フルハーネス型墜落制止用器具を使用するために必要なものはどれか。', '技能講習', '作業主任者の選任', '特別教育の受講', '運転免許', 'C', 'フルハーネス型墜落制止用器具を使用するときは「特別教育」を受講しなければならない。', '安全のしおり 4-3 高所作業 ③', true),
  ('SHIORI-014', '安全のしおり', '高所作業', '★★★', '単管手すりで開口部を養生する場合の手すり高さの基準として正しいものはどれか。', '75cm以上', '85cm以上', '95cm以上', '105cm以上', 'B', '単管手すりで養生する場合、手すり高さ85cm以上、中桟35〜50cm、巾木15cm以上を確保する。', '安全のしおり 4-3 高所作業 図5(開口部養生例)', true),
  ('SHIORI-015', '安全のしおり', '揚重作業(玉掛)', '★★★', '4月に行う吊具(玉掛用具)の月例点検で、使用可能と判定した用具に貼るビニールテープの色はどれか。', '緑', '黄', '赤', '白', 'D', '1・5・9月＝緑、2・6・10月＝黄、3・7・11月＝赤、4・8・12月＝白。発注者・元請に指定色がある場合はそちらを優先する。', '安全のしおり 4-4 揚重作業 ③', true),
  ('SHIORI-016', '安全のしおり', '揚重作業(玉掛)', '★★', 'クレーン等を用いた揚重作業について、正しいものはどれか。', 'ワイヤーによる1本吊りは厳禁である', '吊り荷の下に入ってもよい', 'アウトリガーは張り出さなくてよい', '介錯ロープは使用しない', 'A', 'クレーン等を用いた揚重作業ではワイヤーによる1本吊りは厳禁。吊り荷の下に入らない、アウトリガーは原則最大張出で使用、介錯ロープを使用する。', '安全のしおり 4-4 揚重作業 ⑤(他②④⑦)', true),
  ('SHIORI-017', '安全のしおり', '重機作業', '★★', 'バックホウの運転席から離脱する際の措置として正しいものはどれか。', 'バケットを上げたままにする', 'エンジンを掛けたままにする', 'バケットを地面に下ろし、エンジンを止め、走行ブレーキを掛けてキーを抜く', 'キーは付けたままでよい', 'C', '運転席を離れる際はバケット等を地面に下ろし、エンジンを止め、走行ブレーキを掛けてキーを抜き、逸走を防止する。', '安全のしおり 4-5 重機作業(バックホウ) ⑦', true),
  ('SHIORI-018', '安全のしおり', '重機作業', '★★★', 'バックホウによる荷の吊り上げ作業が認められる条件として正しいものはどれか。', '作業者の判断でいつでも可能', '急いでいるときは無条件で可能', '作業の性質上やむを得ない等の場合で、かつクレーン機能付き重機・移動式クレーン資格・玉掛資格・吊具点検・フック外れ止め等の安全措置を満たす場合のみ', '玉掛資格があれば他の措置は不要', 'C', 'バックホウの荷吊り上げは「作業の性質上やむを得ない/安全な作業遂行上必要」かつ「クレーン機能付き重機・移動式クレーン資格・立入禁止措置・玉掛資格・吊具点検・フック外れ止め等」を共に満たす場合のみ可能。', '安全のしおり 4-5 重機作業(バックホウ) ⑩', true),
  ('SHIORI-019', '安全のしおり', '有害物取扱い', '★★', '化学物質を取り扱う作業で、まず参照してリスクアセスメントを行う資料はどれか。', '作業日報', 'SDS(安全データシート)', '社員名簿', '出面表', 'B', '化学物質の取扱いはSDS(安全データシート)を参照してリスクアセスメントを実施し、関係者に周知する。', '安全のしおり 4-6 有害物取扱い ①', true),
  ('SHIORI-020', '安全のしおり', '酸欠作業', '★', '酸素欠乏危険場所に立ち入る前、安全を確認する酸素濃度の基準はどれか。', '15%以上', '16%以上', '18%以上', '21%以上', 'C', '作業主任者が酸素濃度等を測定し、酸素濃度18%以上の安全を確認してから酸欠等危険場所に立ち入る。', '安全のしおり 4-7 酸素欠乏症等作業 ①', true),
  ('SHIORI-021', '安全のしおり', '酸欠作業', '★★★', '酸素濃度計の校正期間の目安として正しいものはどれか。', '1ヶ月', '6ヶ月', '1年', '校正は不要', 'C', '酸素濃度計等の校正期間は1年を目安に行う。使っていなくてもセンサーは劣化する。', '安全のしおり 4-7 酸素欠乏症等作業 ⑩', true),
  ('SHIORI-022', '安全のしおり', '区画(工事エリア)', '★★', '作業エリアの区画・開口部について正しいものはどれか。', '重機作業と作業員が混在しても区画は不要', '開口部は丈夫な蓋等で塞ぐか、周囲を手すり等で囲んで立入禁止とする', '産業廃棄物の保管場所に囲いは不要', '資機材の仮置きはどこでもよい', 'B', '開口部は丈夫な蓋等で覆って塞ぐか、周囲を手すり等で囲んで立入禁止とする。重機と作業員が混在する場合はバリケード等で区画し、区画できない場合は誘導員(監視人)を配置する。', '安全のしおり 4-1 区画 ④⑦', true),
  ('SHIORI-023', '安全のしおり', '作業後', '★★', '石綿・ダイオキシン特定作業等における記録の取り扱いとして正しいものはどれか。', '記録は不要', '法令に則り記録を保管する', '口頭報告のみでよい', '客先には報告しない', 'B', '日々の現場で日誌・日報を作成・保管し、石綿・ダイオキシン特定作業等においては法令に則り記録を保管する。', '安全のしおり 2-3 作業後 ③', true),
  ('SHIORI-024', '安全のしおり', '作業前', '★★', '有資格作業における作業前の確認事項として正しいものはどれか。', '資格の有無は自己申告でよい', '有資格作業では資格証の原本確認を行う', '確認は作業後でよい', 'コピーがあれば原本は不要', 'B', '有資格作業においては原本の確認を行う。各作業に共通して、作業開始前に資格証の携帯を確認する。', '安全のしおり 2-1 作業前 ⑥(4章共通注記)', true)
